/**
 * Optional verse lookup from BlueGen's own chapter-page translations.
 *
 * verses.json is generated by `node scripts/extract-verses.mjs` from the
 * "Verse N: ..." strings in src/chapters/ChapterN.jsx. It is deliberately a
 * tiny, dependency-free hook: swap verses.json for a larger verified
 * collection later and nothing else in the chatbot needs to change.
 *
 * Coverage note: it holds only what the chapter pages contain (not every
 * verse of all 18 chapters), so a miss means "not in the local library", not
 * "this verse does not exist".
 */
import { readFileSync } from "node:fs";

let VERSES = null;
function load() {
  if (VERSES) return VERSES;
  try {
    VERSES = JSON.parse(readFileSync(new URL("./verses.json", import.meta.url), "utf8"));
  } catch {
    VERSES = {};
  }
  return VERSES;
}

// "2.47", "2:47", "BG 2.47", "chapter 2 verse 47", "ch 2 v 47", "verse 47 of chapter 2"
const PATTERNS = [
  /\b(?:bg|gita|bhagavad\s*gita)?\s*(\d{1,2})\s*[.:]\s*(\d{1,2})\b/gi,
  /\bch(?:apter)?\.?\s*(\d{1,2})\s*,?\s*(?:v(?:erse)?|shloka|sloka)\.?\s*(\d{1,2})\b/gi,
  /\b(?:v(?:erse)?|shloka|sloka)\.?\s*(\d{1,2})\s*(?:of|in)\s*ch(?:apter)?\.?\s*(\d{1,2})\b/gi,
];

export function findVerseRefs(text, max = 3) {
  const found = [];
  const seen = new Set();
  const add = (ch, v) => {
    const c = Number(ch), vv = Number(v);
    if (c < 1 || c > 18 || vv < 1 || vv > 78) return;
    const key = `${c}.${vv}`;
    if (!seen.has(key)) { seen.add(key); found.push(key); }
  };
  for (const [i, re] of PATTERNS.entries()) {
    re.lastIndex = 0;
    let m;
    while ((m = re.exec(text)) && found.length < max) {
      if (i === 2) add(m[2], m[1]); else add(m[1], m[2]);
    }
  }
  return found;
}

export function verseContextFor(text) {
  const verses = load();
  const lines = [];
  for (const key of findVerseRefs(text)) {
    const hit = verses[key];
    if (hit) lines.push(`Bhagavad Gita ${hit.range || key}: ${hit.text}`);
  }
  // de-duplicate ranges that expand to several keys
  return [...new Set(lines)].join("\n");
}
